import * as React from "react"

import { cn } from "@/lib/utils"

export type InspectorPanelProps = React.ComponentPropsWithoutRef<"aside">

export function InspectorPanel({ children, className, ...props }: InspectorPanelProps) {
  return (
    <aside data-slot="inspector-panel" className={cn("flex min-h-80 w-full max-w-sm flex-col bg-sidebar", className)} {...props}>
      {children ?? (<><header className="flex min-h-11 items-center justify-between border-b border-border px-3"><strong className="text-xs uppercase tracking-[0.08em]">Inspector</strong><span className="font-mono text-[10px] text-muted-foreground">Design</span></header><nav className="grid grid-cols-3 gap-1 border-b border-border p-1" aria-label="Inspector sections">{["Scene", "Layer", "Motion"].map((label, index) => <button key={label} type="button" aria-current={index === 0 ? "page" : undefined} className="min-h-11 rounded-[var(--radius-control)] text-xs font-bold text-muted-foreground aria-[current=page]:bg-secondary aria-[current=page]:text-foreground">{label}</button>)}</nav><div className="grid gap-3 overflow-y-auto p-3"><label className="grid gap-1 text-xs font-bold">Scene name<input defaultValue="Reveal" className="min-h-11 rounded-[var(--radius-control)] border border-border bg-input px-3 text-sm font-normal" /></label><label className="grid gap-1 text-xs font-bold">On-screen message<textarea className="min-h-24 rounded-[var(--radius-control)] border border-border bg-input p-3 text-sm font-normal" /></label></div></>)}
    </aside>
  )
}
